// Copies the site's content into the app's assets folder. Run from tools/ after
// `npm install`, whenever the site's data changes:
//
//   node sync-content.mjs            (site at ../../sda-church-nextjs/quiz-qwik or $SITE)
//
// Everything under app/src/main/assets is generated by this script; never edit it by hand.
import { cpSync, existsSync, mkdirSync, readFileSync, readdirSync, rmSync, statSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import { register } from "tsx/esm/api";

const here = dirname(fileURLToPath(import.meta.url));
const SITE = resolve(process.env.SITE ?? "C:/Users/admin/sda-church-nextjs/quiz-qwik");
const ASSETS = resolve(here, "../app/src/main/assets");

if (!existsSync(join(SITE, "src/data/himnario-adventista.json"))) {
  console.error(`site not found at ${SITE} (set SITE=...)`);
  process.exit(1);
}

rmSync(ASSETS, { recursive: true, force: true });
mkdirSync(join(ASSETS, "data"), { recursive: true });

const sizes = [];
function put(rel, content) {
  const target = join(ASSETS, rel);
  mkdirSync(dirname(target), { recursive: true });
  writeFileSync(target, content);
  sizes.push([rel, statSync(target).size]);
}
function copy(relSite, rel) {
  const src = join(SITE, relSite);
  const target = join(ASSETS, rel);
  mkdirSync(dirname(target), { recursive: true });
  cpSync(src, target, { recursive: true });
  const size = statSync(target).isDirectory() ? dirSize(target) : statSync(target).size;
  sizes.push([rel, size]);
}
function dirSize(dir) {
  return readdirSync(dir).reduce((n, f) => {
    const p = join(dir, f);
    return n + (statSync(p).isDirectory() ? dirSize(p) : statSync(p).size);
  }, 0);
}
const json = (v) => JSON.stringify(v);

// ---- plain JSON from the site -------------------------------------------------------------
copy("src/data/himnario-adventista.json", "data/himnario-es.json");
copy("src/data/himnario-pt.json", "data/himnario-pt.json");
copy("src/data/himnario-pt-novo.json", "data/himnario-pt-novo.json");
copy("src/data/bible-books.json", "data/bible-books.json");
copy("public/data/biblia", "data/biblia");
copy("public/data/egw", "data/egw");
copy("public/data/search-index.json", "data/search-index.json");
copy("public/covers", "covers");

// ---- TypeScript-only sources, evaluated with tsx -------------------------------------------
const unregister = register();
const mod = async (rel) => import(pathToFileURL(join(SITE, rel)).href);

const quarterly = (await mod("src/data/quarterly.ts")).default;
put("data/escuela-sabatica.json", json(quarterly));

const { QUIZZES } = await mod("src/data/quizzes/index.ts");
put("data/quizzes.json", json(QUIZZES));

const church = await mod("src/data/church.ts");
put(
  "data/church.json",
  json({
    schedule: church.SCHEDULE,
    location: church.LOCATION,
    mission: church.MISSION,
    hierarchy: church.HIERARCHY,
    timeline: church.TIMELINE,
    pioneers: church.PIONEERS,
  }),
);

const { FEATURED_HYMNS } = await mod("src/utils/featured-hymns.ts");
put("data/featured-hymns.json", json(FEATURED_HYMNS));

const anuncios = await mod("src/data/anuncios.ts");
put("data/anuncios.json", json({ csvUrl: anuncios.ANUNCIOS_CSV_URL, items: anuncios.ANUNCIOS }));

const { HOME_PHOTOS } = await mod("src/data/home-photos.ts");
put("data/home-photos.json", json(HOME_PHOTOS));

const videos = await mod("src/routes/videos/data.ts");
put(
  "data/videos-channels.json",
  json({
    channels: videos.CHANNELS,
    categories: videos.CATS.map((c) => ({ key: c.key, label: c.label, regex: c.regex.source })),
  }),
);
unregister();

// ---- EGW catalogue: module-private consts in egw/index.tsx, lifted out of the source ---------
const egwSrc = readFileSync(join(SITE, "src/routes/egw/index.tsx"), "utf8");
function lift(name) {
  const start = egwSrc.indexOf(`const ${name}`);
  const open = egwSrc.indexOf("[", start);
  const close = egwSrc.indexOf("\n];", open);
  if (start < 0 || open < 0 || close < 0) throw new Error(`cannot find const ${name} in egw/index.tsx`);
  return new Function(`return ${egwSrc.slice(open, close + 2)}`)();
}
const aisles = lift("AISLES");
const books = lift("BOOKS").map((b) => ({ ...b, cover: b.cover.replace(/^\/covers\//, "") }));
put("data/egw-index.json", json({ aisles, books }));
if (books.length !== 25) throw new Error(`expected 25 EGW books, lifted ${books.length}`);

// ---- home: posters + Lottie (image paths rewritten to live beside the JSON) -----------------
const HOME = join(SITE, "public/home");
for (const f of readdirSync(HOME)) if (f.endsWith(".jpg")) copy(`public/home/${f}`, `home/${f}`);
const LOTTIE = join(HOME, "lottie");
for (const f of readdirSync(LOTTIE)) {
  if (!f.endsWith(".json")) continue;
  const data = JSON.parse(readFileSync(join(LOTTIE, f), "utf8"));
  for (const a of data.assets ?? []) {
    // paths become relative to the assets root (lottie-compose imageAssetsFolder = "")
    if (typeof a.u === "string") a.u = a.u.replace(/^\.\.\/\.\.\/covers\//, "covers/").replace(/^img\//, "home/lottie/img/");
  }
  put(`home/lottie/${f}`, JSON.stringify(data));
}
copy("public/home/lottie/img", "home/lottie/img");

// ---- font licences ------------------------------------------------------------------------
for (const f of readdirSync(join(SITE, "src/fonts"))) if (f.startsWith("OFL-")) copy(`src/fonts/${f}`, `licenses/${f}`);

// ---- report -------------------------------------------------------------------------------
let total = 0;
for (const [rel, size] of sizes) {
  total += size;
  console.log(`${(size / 1024).toFixed(0).padStart(7)} KB  ${rel}`);
}
console.log(`${(total / 1024 / 1024).toFixed(1)} MB total → ${ASSETS}`);
